<?php
declare(strict_types=1);
$root=sys_get_temp_dir().DIRECTORY_SEPARATOR.'kalite-filo-campaign-'.bin2hex(random_bytes(5));function kalite_filo_admin_config():array{global $root;return ['data_root'=>$root];}function kalite_filo_admin_ensure_private_directory(string $path):void{if(!is_dir($path)&&!mkdir($path,0700,true)&&!is_dir($path))throw new RuntimeException('directory');}function campaign_test_assert(bool $condition,string $message):void{if(!$condition)throw new RuntimeException($message);}function campaign_test_remove(string $path):void{if(!is_dir($path))return;foreach(scandir($path)?:[] as $entry){if($entry==='.'||$entry==='..')continue;$item=$path.DIRECTORY_SEPARATOR.$entry;is_dir($item)?campaign_test_remove($item):@unlink($item);}@rmdir($path);}require_once dirname(__DIR__).'/campaign-store.php';
try{$campaign=kalite_filo_admin_normalize_campaign(['name'=>'Ağustos Bülteni','subject'=>'Filo gündemi','preheader'=>'Yeni içerikler','content'=>[['type'=>'hero','heading'=>'Kalite Filo','text'=>'Aylık filo gündemi'],['type'=>'cta','label'=>'İncele','url'=>'https://kalitefilo.com.tr/filo-rehberi/']]]);campaign_test_assert($campaign['status']==='draft'&&$campaign['revision']===1&&count($campaign['content'])===2,'Campaign draft schema must normalize.');$updated=kalite_filo_admin_normalize_campaign(['name'=>'Ağustos Bülteni','subject'=>'Güncel konu','content'=>[['type'=>'text','text'=>'İçerik']]],$campaign);campaign_test_assert($updated['id']===$campaign['id']&&$updated['revision']===2,'Campaign edit must preserve identity and revision.');$lock=kalite_filo_admin_lock_campaign_store();try{kalite_filo_admin_write_campaign_records([$updated]);}finally{kalite_filo_admin_unlock_campaign_store($lock);}campaign_test_assert(kalite_filo_admin_campaign_records()[0]['subject']==='Güncel konu','Campaign store must round-trip atomically.');$rows=[['email'=>'eligible@example.com','status'=>'approved','consent_at'=>'2026-08-01 10:00:00','consent_text_version'=>'v1','iys_status'=>'synced','unsubscribed_at'=>''],['email'=>'lead@example.com','status'=>'lead_only','consent_at'=>'','consent_text_version'=>'','iys_status'=>'not_requested','unsubscribed_at'=>''],['email'=>'removed@example.com','status'=>'approved','consent_at'=>'2026-08-01 10:00:00','consent_text_version'=>'v1','iys_status'=>'approved','unsubscribed_at'=>'2026-08-02 10:00:00']];$staging=kalite_filo_admin_campaign_audience_summary($rows,'staging');campaign_test_assert($staging['eligible']===1&&$staging['sendable']===0&&$staging['environmentBlocked']===1,'Staging audience must remain blocked even when legally eligible.');$production=kalite_filo_admin_campaign_audience_summary($rows,'production');campaign_test_assert($production['sendable']===1&&$production['missingConsent']===1&&$production['unsubscribed']===1,'Eligibility must fail closed by consent and unsubscribe.');try{kalite_filo_admin_normalize_campaign(['name'=>'Unsafe','subject'=>"Header\nInjection",'content'=>[['type'=>'text','text'=>'Body']]]);campaign_test_assert(false,'Header injection must fail.');}catch(InvalidArgumentException){/* expected */}}finally{campaign_test_remove($root);}fwrite(STDOUT,"Admin campaign store tests passed.\n");
